@RequiredArgsConstructor
public class RestClientConfig {

    private final ResourceLoader resourceLoader;

    @org.springframework.beans.factory.annotation.Value(
            "${customs.services.get-client-for-sepa.ssl.trust-store:}")
    private String trustStore;

    @org.springframework.beans.factory.annotation.Value(
            "${customs.services.get-client-for-sepa.ssl.trust-store-password:}")
    private String trustStorePassword;

    @org.springframework.beans.factory.annotation.Value(
            "${customs.services.get-client-for-sepa.ssl.trust-store-type:JKS}")
    private String trustStoreType;

    @PostConstruct
    public void configureSslContext() {
        if (trustStore == null || trustStore.isBlank()) {
            return;
        }
        try {
            Resource resource = resourceLoader.getResource(trustStore);
            if (!resource.exists()) {
                throw new IllegalStateException("Truststore not found: " + trustStore);
            }
            KeyStore keyStore = KeyStore.getInstance(trustStoreType);
            try (InputStream input = resource.getInputStream()) {
                keyStore.load(input, trustStorePassword != null ? trustStorePassword.toCharArray() : null);
            }
            TrustManagerFactory tmf = TrustManagerFactory.getInstance(TrustManagerFactory.getDefaultAlgorithm());
            tmf.init(keyStore);
            SSLContext sslContext = SSLContext.getInstance("TLS");
            sslContext.init(null, tmf.getTrustManagers(), null);
            javax.net.ssl.HttpsURLConnection.setDefaultSSLSocketFactory(sslContext.getSocketFactory());
        } catch (Exception e) {
            throw new IllegalStateException("Failed to initialize SSL truststore for GetClientForSepa", e);
        }
    }

    @Bean
    public RestTemplate restTemplate(RestTemplateBuilder builder) {
        return builder.build();
    }
}

