package rs.unicredit.cbr.service;

import java.net.URI;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.ResponseEntity;
import org.springframework.stereotype.Service;
import org.springframework.web.client.RestTemplate;
import org.springframework.web.util.UriComponentsBuilder;

import lombok.RequiredArgsConstructor;
import rs.unicredit.cbr.dto.GetClientForSepaResponse.ClientData;
import rs.unicredit.cbr.model.CbrTransaction;
import rs.unicredit.cbr.model.CbrTransactionRequest;
import rs.unicredit.cbr.repository.CbrTransactionRepository;
import rs.unicredit.cbr.repository.CbrTransactionRequestRepository;

@Service
@RequiredArgsConstructor
public class GetClientForSepaService {

    public enum AccountRole {
        DEBTOR,
        CREDITOR
    }

    private final RestTemplate restTemplate;
    private final com.fasterxml.jackson.databind.ObjectMapper objectMapper;
    private final CbrTransactionRepository transactionRepository;
    private final CbrTransactionRequestRepository requestRepository;

    @Value("${customs.services.get-client-for-sepa.base-url}")
    private String baseUrl;

    public ClientData fetchAndUpdateByAccount(String account, Long requestId) {
        return fetchAndUpdateByAccount(account, requestId, AccountRole.DEBTOR);
    }

    public ClientData fetchAndUpdateByAccount(String account, Long requestId, AccountRole role) {
        URI uri = UriComponentsBuilder.fromHttpUrl(baseUrl)
                .path("/clients")
                .queryParam("p_account", account)
                .build(true)
                .toUri();
        ResponseEntity<com.fasterxml.jackson.databind.JsonNode> response =
                restTemplate.getForEntity(uri, com.fasterxml.jackson.databind.JsonNode.class);
        if (!response.getStatusCode().is2xxSuccessful()) {
            return null;
        }
        com.fasterxml.jackson.databind.JsonNode root = response.getBody();
        if (root == null) {
            return null;
        }
        com.fasterxml.jackson.databind.JsonNode clientNode = root.hasNonNull("client") ? root.get("client") : root;
        ClientData clientData;
        try {
            clientData = objectMapper.treeToValue(clientNode, ClientData.class);
        } catch (com.fasterxml.jackson.core.JsonProcessingException e) {
            throw new IllegalStateException("Failed to parse GetClientForSepa response", e);
        }
        if (clientData == null) {
            return null;
        }
        CbrTransactionRequest request = requestRepository.findById(requestId)
                .orElseThrow(() -> new IllegalArgumentException("Request not found: " + requestId));
        CbrTransaction txn = transactionRepository.findFirstByRequestId(requestId);
        if (txn == null) {
            throw new IllegalArgumentException("Transaction not found for request id: " + requestId);
        }
        if (role == AccountRole.DEBTOR) {
            txn.setDebtorCoreId(clientData.cltId());
            txn.setDebtorLrc(clientData.lrc());
            txn.setDebtorSegment(clientData.segment());
            txn.setDebtorCountryCode(clientData.countryCode());
            txn.setDebtorCustomerId(clientData.maticni());
            txn.setDebtorRezident(clientData.rezident());
        } else if (role == AccountRole.CREDITOR) {
            txn.setCreditorCoreId(clientData.cltId());
            txn.setCreditorLrc(clientData.lrc());
            txn.setCreditorSegment(clientData.segment());
            txn.setCreditorCountryCode(clientData.countryCode());
            txn.setCreditorCustomerId(clientData.maticni());
            txn.setCreditorRezident(clientData.rezident());
        }
        if (clientData.lei() != null) {
            if (txn.getMessageType() == rs.unicredit.cbr.model.MessageType.P8) {
                txn.setDebtorIdLei(clientData.lei());
            } else if (txn.getMessageType() == rs.unicredit.cbr.model.MessageType.P4) {
                txn.setCreditorIdLei(clientData.lei());
            }
        }
        txn.setStatus("S3");
        request.setStatus("S3");
        transactionRepository.save(txn);
        requestRepository.save(request);
