    private void applySplitDetails(XPath xpath, Document doc, CbrTransaction txn)
            throws XPathExpressionException {
        NodeList nodes = (NodeList) xpath.evaluate(
                "/urn:Document/urn:FIToFICstmrCdtTrf/urn:CdtTrfTxInf/iso:RgltryRptg/iso:Dtls",
                doc, XPathConstants.NODESET);
        if (nodes == null || nodes.getLength() == 0) {
            return;
        }
        for (int i = 0; i < nodes.getLength(); i++) {
            Node node = nodes.item(i);
            String splitStatCode = text(xpath, node, "iso:Cd");
            String amountStr = text(xpath, node, "iso:Amt");
            String amountCcy = attr(xpath, node, "iso:Amt/@Ccy");

            String invoiceNumber = null;
            String invoiceYear = null;
            NodeList infos = (NodeList) xpath.evaluate("iso:Inf", node, XPathConstants.NODESET);
            for (int j = 0; j < infos.getLength(); j++) {
                String info = infos.item(j).getTextContent();
                if (!notBlank(info)) {
                    continue;
                }
                String trimmed = info.trim();
                String numberValue = extractInfValue(trimmed, "/CN/", "/IN/");
                if (numberValue != null) {
                    invoiceNumber = numberValue;
                    continue;
                }
                String yearValue = extractInfValue(trimmed, "/CY/", "/IY/", "/IC/");
                if (yearValue != null) {
                    invoiceYear = yearValue;
                }
            }

            CbrTransactionStat stat = new CbrTransactionStat();
            stat.setTransaction(txn);
            stat.setSplitStatCode(splitStatCode);
            stat.setSplitAmount(parseAmount(amountStr));
            stat.setSplitAmountCurrency(amountCcy);
            stat.setInvoiceNumber(invoiceNumber);
            stat.setInvoiceYear(extractYear(invoiceYear));
            txn.getRegulatoryDetails().add(stat);
        }
    }

    private String extractYear(String value) {
        if (!notBlank(value)) {
            return null;
        }
        String trimmed = value.trim();
        if (trimmed.length() >= 4 && trimmed.matches("\\d{4}.*")) {
            return trimmed.substring(0, 4);
        }
        return trimmed;
    }

    private String extractInfValue(String value, String... prefixes) {
        if (!notBlank(value)) {
            return null;
        }
        for (String prefix : prefixes) {
            int idx = value.indexOf(prefix);
            if (idx >= 0) {
                return value.substring(idx + prefix.length()).trim();
            }
        }
